select id, product_id, quantity, sum(quantity) over (partition by store_id, product_id order by last_restock, id rows between unbounded preceding and current row) as cumulative_quantity, sum(quantity) over (partition by store_id order by quantity, id rows between unbounded preceding and current row) as running_quantity, avg(quantity) over (order by quantity, id rows between 2 preceding and current row) as quantity_avg_2 from inventory;
